import csv, re
from collections import defaultdict

# Build catalog: point_uri -> (tsid, point_class)
cat = {}
with open(CATALOG_CSV, encoding='utf-8') as f:
    for row in csv.DictReader(f):
        cat[row['point_uri']] = row['timeseries_id']

# Map tsid -> values at target timestamp
target = '2018-04-22 16:00'
vals = {}
with open(VALUES_CSV, encoding='utf-8') as f:
    for row in csv.DictReader(f):
        if row['timestamp'] == target:
            vals[row['timeseries_id']] = float(row['value'])

base = 'http://buildgraph.org/BG_medium_office_2004_0000#'
results = []
for uri, tsid in cat.items():
    if uri.startswith(base):
        name = uri[len(base):]
        zone, point = name.split('.', 1)
        if point == 'Zone_Air_Temperature_Sensor':
            results.append((zone, point, tsid))
        if point == 'Zone_Air_Cooling_Temperature_Setpoint':
            results.append((zone, point, tsid))

# Group by zone
zones = defaultdict(dict)
for zone, point, tsid in results:
    zones[zone][point] = tsid

out = []
for zone, pts in sorted(zones.items()):
    if 'Zone_Air_Temperature_Sensor' in pts and 'Zone_Air_Cooling_Temperature_Setpoint' in pts:
        t = vals.get(pts['Zone_Air_Temperature_Sensor'])
        s = vals.get(pts['Zone_Air_Cooling_Temperature_Setpoint'])
        if t is not None and s is not None:
            out.append((zone, t, s, t - s))

out.sort(key=lambda x: -x[3])
for z in out:
    print(z)

